import './globals.css';
import { Inter } from 'next/font/google';

const inter = Inter({ subsets: ['latin'] });

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body className={`${inter.className} bg-[#0f172a] text-[#f8fafc]`}>
        <nav className="border-b border-[#1e293b] p-4 flex justify-between items-center">
          <div className="font-bold text-[#f8fafc] tracking-widest">SQUINT</div>
        </nav>
        <main className="min-h-screen flex flex-col">{children}</main>
      </body>
    </html>
  );
}

import { create } from 'zustand';

interface VibeState {
  activeLayer: 'reality' | 'value' | 'temperature' | 'shape';
  intensity: number;
  setLayer: (layer: VibeState['activeLayer']) => void;
  setIntensity: (intensity: number) => void;
}

export const useVibeStore = create<VibeState>((set) => ({
  activeLayer: 'reality',
  intensity: 50,
  setLayer: (layer) => set({ activeLayer: layer }),
  setIntensity: (intensity) => set({ intensity }),
}));

"use client";
import Link from 'next/link';
import { motion } from 'framer-motion';
import { ReactNode } from 'react';

interface SovereignLinkProps {
  href: string;
  children: ReactNode;
}

export function SovereignLink({ href, children }: SovereignLinkProps) {
  return (
    <Link href={href} passHref legacyBehavior>
      <motion.a
        whileHover={{ scale: 1.02, color: "#3b82f6" }}
        whileTap={{ scale: 0.98 }}
        className="transition-colors duration-200 text-[#94a3b8] hover:text-[#f8fafc] cursor-pointer"
      >
        {children}
      </motion.a>
    </Link>
  );
}

import { getPerceptionData } from '@/lib/actions';
import { notFound } from 'next/navigation';

interface PageProps {
  params: { slug: string };
}

export default async function EnginePage({ params }: PageProps) {
  const data = await getPerceptionData(params.slug);
  if (!data) return notFound();

  return (
    <div className="flex flex-col items-center justify-center p-8 space-y-6 flex-1">
      <header className="text-center space-y-2">
        <h1 className="text-2xl font-semibold text-[#f8fafc]">{data.title}</h1>
        <p className="text-[#94a3b8]">{data.description}</p>
      </header>
      <section className="w-full max-w-4xl bg-[#1e293b] aspect-video rounded-md flex items-center justify-center border border-[#3b82f6]/20 relative overflow-hidden">
        <div className="absolute inset-0 flex items-center justify-center text-[#94a3b8]">
          [Engine Viewport: {params.slug}]
        </div>
      </section>
    </div>
  );
}

"use server";
import { revalidatePath } from 'next/cache';

export async function getPerceptionData(slug: string) {
  const registry: Record<string, { title: string; description: string }> = {
    'value-study': { title: 'Value Simplification', description: 'Collapse reality into 3 value masses.' },
    'warm-cool': { title: 'Temperature Mapping', description: 'Isolate warm light from cool shadow.' },
  };
  return registry[slug] || null;
}

export async function savePerceptionState(slug: string, stateData: any) {
  await new Promise(resolve => setTimeout(resolve, 500));
  revalidatePath(`/engine/${slug}`);
  return { success: true, timestamp: Date.now() };
}
